"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["7248"],{39382(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/06/11/cve-2026-49328","metadata":{"permalink":"/zh-cn/blog/2026/06/11/cve-2026-49328","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2026-06-11-cve-2026-49328.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2026-06-11-cve-2026-49328.md","title":"CVE-2026-49328 - Apache Fesod (Incubating): \u5BF9\u7528\u6237\u63D0\u4F9B\u7684URL\u9A8C\u8BC1\u4E0D\u5F53\u5BFC\u81F4SSRF\u6F0F\u6D1E","description":"\u5173\u4E8E CVE-2026-49328 \u7684\u5B89\u5168\u901A\u544A.","date":"2026-06-11T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/zh-cn/blog/tags/announcement"},{"inline":true,"label":"security","permalink":"/zh-cn/blog/tags/security"},{"inline":true,"label":"CVE-2026-49328","permalink":"/zh-cn/blog/tags/cve-2026-49328"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"CVE-2026-49328 - Apache Fesod (Incubating): \u5BF9\u7528\u6237\u63D0\u4F9B\u7684URL\u9A8C\u8BC1\u4E0D\u5F53\u5BFC\u81F4SSRF\u6F0F\u6D1E","description":"\u5173\u4E8E CVE-2026-49328 \u7684\u5B89\u5168\u901A\u544A.","tags":["announcement","security","CVE-2026-49328"]},"unlisted":false,"nextItem":{"title":"\u4F7F\u7528 OpenRewrite \u4ECE FastExcel 1.3.0 \u81EA\u52A8\u8FC1\u79FB\u5230 Apache Fesod (Incubating)","permalink":"/zh-cn/blog/2026/05/07/migration-from-fastexcel-with-openrewrite"}},"content":"\x3c!--\\n- Licensed to the Apache Software Foundation (ASF) under one or more\\n- contributor license agreements.  See the NOTICE file distributed with\\n- this work for additional information regarding copyright ownership.\\n- The ASF licenses this file to You under the Apache License, Version 2.0\\n- (the \\"License\\"); you may not use this file except in compliance with\\n- the License.  You may obtain a copy of the License at\\n-\\n-   http://www.apache.org/licenses/LICENSE-2.0\\n-\\n- Unless required by applicable law or agreed to in writing, software\\n- distributed under the License is distributed on an \\"AS IS\\" BASIS,\\n- WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n- See the License for the specific language governing permissions and\\n- limitations under the License.\\n--\x3e\\n\\n\u5173\u4E8E Apache Fesod (Incubating) \u4E2D\u670D\u52A1\u5668\u7AEF\u8BF7\u6C42\u4F2A\u9020\uFF08SSRF\uFF09\u6F0F\u6D1E **CVE-2026-49328** \u7684\u5B89\u5168\u901A\u544A\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n## \u6F0F\u6D1E\u63CF\u8FF0\\n\\nApache Fesod (Incubating) \u7684 `fesod-sheet` \u6A21\u5757\u4E2D `UrlImageConverter` \u7EC4\u4EF6\u5B58\u5728\u670D\u52A1\u5668\u7AEF\u8BF7\u6C42\u4F2A\u9020\uFF08SSRF\uFF09\u6F0F\u6D1E\u3002\u653B\u51FB\u8005\u53EF\u4EE5\u901A\u8FC7\u63D0\u4F9B\u6076\u610F\u7684\u56FE\u7247 URL\uFF0C\u8BF1\u4F7F\u7CFB\u7EDF\u5411\u5185\u90E8\u7F51\u7EDC\u6216\u5176\u4ED6\u53D7\u9650\u8D44\u6E90\u53D1\u8D77\u51FA\u7AD9\u7F51\u7EDC\u8BF7\u6C42\u3002\\n\\n## \u53D7\u5F71\u54CD\u7684\u6A21\u5757\u4E0E\u7248\u672C\\n\\nFesod Spreadsheet (`fesod-sheet`):\\n\\n- 2.0.1-incubating\\n\\n## \u4FEE\u590D\u5EFA\u8BAE\\n\\n\u5EFA\u8BAE\u53D7\u5F71\u54CD\u7248\u672C\u7684\u7528\u6237\u5C3D\u5FEB\u5347\u7EA7\u5230\u5BF9\u5E94\u7684\u4FEE\u590D\u7248\u672C\u3002\\n\\n| \u53D7\u5F71\u54CD\u7248\u672C            | \u4FEE\u590D\u7248\u672C             |\\n|------------------|------------------|\\n| 2.0.1-incubating | 2.0.2-incubating |\\n\\n## \u53C2\u8003\u94FE\u63A5\\n\\n- [https://github.com/apache/fesod/pull/917](https://github.com/apache/fesod/pull/917)\\n- [https://github.com/apache/fesod/releases/tag/2.0.2-incubating](https://github.com/apache/fesod/releases/tag/2.0.2-incubating)\\n- [https://fesod.apache.org/docs/download](https://fesod.apache.org/docs/download)\\n- [https://lists.apache.org/thread/c1pb5b66h02p9tlrnfbwcgcz85v16fkj](https://lists.apache.org/thread/c1pb5b66h02p9tlrnfbwcgcz85v16fkj)"},{"id":"/2026/05/07/migration-from-fastexcel-with-openrewrite","metadata":{"permalink":"/zh-cn/blog/2026/05/07/migration-from-fastexcel-with-openrewrite","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2026-05-07-migration-from-fastexcel-with-openrewrite.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2026-05-07-migration-from-fastexcel-with-openrewrite.md","title":"\u4F7F\u7528 OpenRewrite \u4ECE FastExcel 1.3.0 \u81EA\u52A8\u8FC1\u79FB\u5230 Apache Fesod (Incubating)","description":"\u5C06 FastExcel 1.3 \u8FC1\u79FB\u81F3 Apache Fesod (Incubating) 2.0.1-incubating","date":"2026-05-07T00:00:00.000Z","tags":[{"inline":true,"label":"migration","permalink":"/zh-cn/blog/tags/migration"},{"inline":true,"label":"fastexcel","permalink":"/zh-cn/blog/tags/fastexcel"},{"inline":true,"label":"fesod","permalink":"/zh-cn/blog/tags/fesod"}],"hasTruncateMarker":true,"authors":[{"name":"Jing Yang","url":"https://github.com/bengbengbalabalabeng","socials":{"github":"https://github.com/bengbengbalabalabeng"},"imageURL":"data:image/png;base64,","key":"bengbengbalabalabeng","page":null}],"frontMatter":{"title":"\u4F7F\u7528 OpenRewrite \u4ECE FastExcel 1.3.0 \u81EA\u52A8\u8FC1\u79FB\u5230 Apache Fesod (Incubating)","description":"\u5C06 FastExcel 1.3 \u8FC1\u79FB\u81F3 Apache Fesod (Incubating) 2.0.1-incubating","authors":["bengbengbalabalabeng"],"tags":["migration","fastexcel","fesod"]},"unlisted":false,"prevItem":{"title":"CVE-2026-49328 - Apache Fesod (Incubating): \u5BF9\u7528\u6237\u63D0\u4F9B\u7684URL\u9A8C\u8BC1\u4E0D\u5F53\u5BFC\u81F4SSRF\u6F0F\u6D1E","permalink":"/zh-cn/blog/2026/06/11/cve-2026-49328"},"nextItem":{"title":"\u4ECE\u4F7F\u7528\u8005\u5230 Committer","permalink":"/zh-cn/blog/2026/04/29/from-user-to-committer"}},"content":"\x3c!--\\n- Licensed to the Apache Software Foundation (ASF) under one or more\\n- contributor license agreements.  See the NOTICE file distributed with\\n- this work for additional information regarding copyright ownership.\\n- The ASF licenses this file to You under the Apache License, Version 2.0\\n- (the \\"License\\"); you may not use this file except in compliance with\\n- the License.  You may obtain a copy of the License at\\n-\\n-   http://www.apache.org/licenses/LICENSE-2.0\\n-\\n- Unless required by applicable law or agreed to in writing, software\\n- distributed under the License is distributed on an \\"AS IS\\" BASIS,\\n- WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n- See the License for the specific language governing permissions and\\n- limitations under the License.\\n--\x3e\\n\\n> \u672C\u6587\u4ECB\u7ECD\u5982\u4F55\u5229\u7528 OpenRewrite \u7F16\u5199\u58F0\u660E\u5F0F\u8FC1\u79FB\u914D\u7F6E\uFF0C\u5C06\u9879\u76EE\u4ECE `cn.idev.excel:fastexcel:1.3.0` \u8FC1\u79FB\u81F3 `org.apache.fesod:fesod-sheet:2.0.1-incubating`\uFF0C\u9002\u7528\u4E8E Maven \u4E0E Gradle \u9879\u76EE\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n## \u80CC\u666F\\n\\nFastExcel\uFF08`cn.idev.excel`\uFF09\u5DF2\u6350\u8D60\u7ED9 Apache \u8F6F\u4EF6\u57FA\u91D1\u4F1A\uFF0C\u5B75\u5316\u4E3A **Apache Fesod (Incubating)**\u3002\u8FC1\u79FB\u7684\u6838\u5FC3\u53D8\u5316\u662F **Java \u5305\u8DEF\u5F84\u66FF\u6362**\u2014\u2014API\u3001\u6CE8\u89E3\u548C\u5904\u7406\u903B\u8F91\u5B8C\u5168\u4E00\u81F4\uFF0C\u5C5E\u4E8E\u4F4E\u98CE\u9669\u7684\u673A\u68B0\u91CD\u6784\u3002\\n\\n\u5B98\u65B9\u8FC1\u79FB\u7B56\u7565\u53C2\u8003\uFF1A[https://fesod.apache.org/docs/migration/from-fastexcel/](https://fesod.apache.org/docs/migration/from-fastexcel/)\\n\\n\u624B\u52A8\u9010\u6587\u4EF6\u66FF\u6362 import \u65E2\u8017\u65F6\u53C8\u5BB9\u6613\u9057\u6F0F\u3002OpenRewrite \u63D0\u4F9B\u4E86 AST \u7EA7\u522B\u7684\u4EE3\u7801\u53D8\u6362\u80FD\u529B\uFF0C\u80FD\u7CBE\u786E\u3001\u5B89\u5168\u5730\u5B8C\u6210\u8FD9\u7C7B\u6279\u91CF\u8FC1\u79FB\u3002\\n\\n## \u8FC1\u79FB\u8303\u56F4\\n\\n1. \u66F4\u65B0 Maven/Gradle \u4F9D\u8D56\\n2. \u5C06\u5DF2\u5E9F\u5F03\u7684\u7C7B\u540D\u66FF\u6362\u4E3A `FesodSheet`\\n3. \u66F4\u65B0\u5305\u5BFC\u5165\\n\\n## \u7F16\u5199 OpenRewrite Recipe\\n\\n\u5728\u9879\u76EE\u6839\u76EE\u5F55\u521B\u5EFA\u6587\u4EF6 `rewrite.yml`\uFF1A\\n\\n```yaml\\n---\\ntype: specs.openrewrite.org/v1beta/recipe\\nname: org.apache.fesod.MigrateFastExcelToFesod\\ndisplayName: Migrate FastExcel 1.3 to Apache Fesod (Incubating) 2.0.1-incubating\\nrecipeList:\\n\\n  # \u6B65\u9AA4 1\uFF1A\u66F4\u65B0\u4F9D\u8D56 (Maven & Gradle)\\n  - org.openrewrite.maven.ChangeDependencyGroupIdAndArtifactId:\\n      oldGroupId: cn.idev.excel\\n      oldArtifactId: fastexcel\\n      newGroupId: org.apache.fesod\\n      newArtifactId: fesod-sheet\\n      newVersion: 2.0.1-incubating\\n  - org.openrewrite.gradle.ChangeDependency:\\n      oldGroupId: cn.idev.excel\\n      oldArtifactId: fastexcel\\n      newGroupId: org.apache.fesod\\n      newArtifactId: fesod-sheet\\n      newVersion: 2.0.1-incubating\\n\\n  # \u6B65\u9AA4 2\uFF1A\u66F4\u65B0\u5305\u5BFC\u5165\\n  - org.openrewrite.java.ChangePackage:\\n      oldPackageName: cn.idev.excel\\n      newPackageName: org.apache.fesod.sheet\\n      recursive: true\\n  - org.openrewrite.java.ChangePackage:\\n      oldPackageName: org.apache.fesod.excel\\n      newPackageName: org.apache.fesod.sheet\\n      recursive: true\\n\\n  # \u6B65\u9AA4 3\uFF1A\u91CD\u547D\u540D\u5165\u53E3\u7C7B\\n  - org.openrewrite.java.ChangeType:\\n      oldFullyQualifiedTypeName: org.apache.fesod.sheet.FastExcel\\n      newFullyQualifiedTypeName: org.apache.fesod.sheet.FesodSheet\\n  - org.openrewrite.java.ChangeType:\\n      oldFullyQualifiedTypeName: org.apache.fesod.sheet.FastExcelFactory\\n      newFullyQualifiedTypeName: org.apache.fesod.sheet.FesodSheet\\n\\n  - org.openrewrite.text.FindAndReplace:\\n      find: ByFastExcelCGLIB\\n      replace: ByFesodCGLIB\\n      filePattern: \\"**/*.java\\"\\n```\\n\\n### \u6267\u884C\u903B\u8F91\u89E3\u6790\\n\\nRecipe \u6309\u58F0\u660E\u987A\u5E8F\u4F9D\u6B21\u6267\u884C\uFF0C\u5206\u4E3A\u56DB\u4E2A\u6B65\u9AA4\uFF1A\\n\\n**Step 1 \u2014 \u66F4\u65B0\u4F9D\u8D56**\uFF1AMaven \u9879\u76EE\u89E6\u53D1\u7B2C\u4E00\u6761\u89C4\u5219\u4FEE\u6539 `pom.xml`\uFF1BGradle \u9879\u76EE\u89E6\u53D1\u7B2C\u4E8C\u6761\u89C4\u5219\u4FEE\u6539 `build.gradle` / `build.gradle.kts`\u3002\u5982\u679C\u9879\u76EE\u53EA\u4F7F\u7528\u5176\u4E2D\u4E00\u79CD\u6784\u5EFA\u5DE5\u5177\uFF0C\u53E6\u4E00\u6761\u89C4\u5219\u81EA\u52A8\u8DF3\u8FC7\uFF0C\u4E0D\u4F1A\u62A5\u9519\u3002\\n\\n**Step 2 \u2014 \u66F4\u65B0\u5305\u5BFC\u5165**\uFF1A`ChangePackage(recursive=true)` \u4E00\u6761\u89C4\u5219\u8986\u76D6 `cn.idev.excel` \u4E0B\u6240\u6709\u5B50\u5305\uFF08annotation\u3001read\u3001write\u3001converters\u3001enums \u7B49\uFF09\uFF0C\u65E0\u9700\u9010\u4E2A\u679A\u4E3E\u3002\u7B2C\u4E8C\u6761\u89C4\u5219\u5904\u7406\u5DF2\u90E8\u5206\u8FC1\u79FB\u5230 `org.apache.fesod.excel` \u7684\u9057\u7559\u4EE3\u7801\u3002\u8FD9\u4E00\u6B65\u4F1A\u5C06 `cn.idev.excel.FastExcel` \u7684 import \u6539\u4E3A `org.apache.fesod.sheet.FastExcel`\uFF08Fesod \u4E2D\u7684 `@Deprecated` \u6865\u63A5\u7C7B\uFF09\u3002\\n\\n**Step 3 \u2014 \u91CD\u547D\u540D\u5165\u53E3\u7C7B**\uFF1AStep 2 \u5B8C\u6210\u540E\uFF0C\u6240\u6709 `FastExcel` \u548C `FastExcelFactory` \u7684 import \u5DF2\u7EDF\u4E00\u6307\u5411 `org.apache.fesod.sheet` \u5305\u3002\u6B64\u65F6\u53EA\u9700\u4E24\u6761 `ChangeType` \u89C4\u5219\uFF0C\u5C06\u5B83\u4EEC\u6539\u4E3A\u6B63\u5F0F\u7684 `FesodSheet` \u7C7B\uFF0C\u540C\u65F6\u81EA\u52A8\u5904\u7406\u6240\u6709\u8C03\u7528\u70B9\uFF08`FastExcel.read()`\u3001`FastExcel.write()` \u7B49\uFF09\u548C\u7C7B\u578B\u5F15\u7528\uFF08\u53D8\u91CF\u58F0\u660E\u3001\u7C7B\u5B57\u9762\u91CF\uFF09\u3002\\n\\n**Step 4 \u2014 CGLIB \u5B57\u7B26\u4E32\u66FF\u6362**\uFF1A\u4EC5\u5BF9\u5F15\u7528\u4E86 CGLIB \u751F\u6210\u7C7B\u540D\u7684\u4EE3\u7801\u751F\u6548\uFF0C\u591A\u6570\u9879\u76EE\u4E0D\u9700\u8981\u6B64\u6B65\u9AA4\uFF0C\u4E0D\u5339\u914D\u5219\u81EA\u52A8\u8DF3\u8FC7\u3002\\n\\n## \u5728\u9879\u76EE\u4E2D\u5F15\u5165 OpenRewrite\\n\\n### Maven \u9879\u76EE\\n\\n\u5728 `pom.xml` \u4E2D\u6DFB\u52A0\u63D2\u4EF6\uFF1A\\n\\n```xml\\n<plugin>\\n    <groupId>org.openrewrite.maven</groupId>\\n    <artifactId>rewrite-maven-plugin</artifactId>\\n    <version>6.38.0</version>\\n    <configuration>\\n        <activeRecipes>\\n            <recipe>org.apache.fesod.MigrateFastExcelToFesod</recipe>\\n        </activeRecipes>\\n    </configuration>\\n</plugin>\\n```\\n\\n### Gradle (Groovy)\\n\\n\u5728 `build.gradle` \u4E2D\u5F15\u5165\uFF1A\\n\\n```groovy\\nplugins {\\n    id \'java\'\\n    id \'maven-publish\'\\n    id \'org.openrewrite.rewrite\' version \'7.32.2\'\\n}\\n\\nrewrite {\\n    activeRecipe(\\n            \'org.apache.fesod.MigrateFastExcelToFesod\',\\n    )\\n}\\n```\\n\\n### Gradle (Kotlin)\\n\\n```kotlin\\nplugins {\\n    `java-library`\\n    `maven-publish`\\n    id(\\"org.openrewrite.rewrite\\") version \\"7.32.2\\"\\n}\\n\\nrewrite {\\n    activeRecipe(\\n        \\"org.apache.fesod.MigrateFastExcelToFesod\\",\\n    )\\n}\\n```\\n\\n## \u6267\u884C\u8FC1\u79FB\\n\\n### \u9884\u89C8\u53D8\u66F4\\n\\n\u5148\u67E5\u770B Recipe \u4F1A\u4EA7\u751F\u54EA\u4E9B\u4FEE\u6539\uFF0C\u4E0D\u5B9E\u9645\u6539\u52A8\u6587\u4EF6\uFF1A\\n\\n```bash\\n# Maven\\n# \u9ED8\u8BA4\u8F93\u51FA\u8DEF\u5F84\uFF1Atarget/site/rewrite/rewrite.patch\\nmvn rewrite:dryRun\\n\\n# Gradle\\n# \u9ED8\u8BA4\u8F93\u51FA\u8DEF\u5F84\uFF1Abuild/reports/rewrite/rewrite.patch\\ngradle rewriteDryRun\\n```\\n\\n\u8F93\u51FA\u4F1A\u5217\u51FA\u6240\u6709\u5373\u5C06\u4FEE\u6539\u7684\u6587\u4EF6\u548C\u5177\u4F53\u53D8\u66F4\u5185\u5BB9\u3002\\n\\n### \u6267\u884C\u8FC1\u79FB\\n\\n\u786E\u8BA4\u65E0\u8BEF\u540E\uFF0C\u6267\u884C\u5B9E\u9645\u4FEE\u6539\uFF1A\\n\\n```bash\\n# Maven\\nmvn rewrite:run\\n\\n# Gradle\\ngradle rewriteRun\\n```\\n\\n### \u9A8C\u8BC1\\n\\n```bash\\n# \u7F16\u8BD1\u68C0\u67E5\\nmvn compile\\n# \u6216\\ngradle compileJava\\n\\n# \u8FD0\u884C\u6D4B\u8BD5\\nmvn test\\n# \u6216\\ngradle test\\n```\\n\\n## \u8FC1\u79FB\u6548\u679C\u793A\u4F8B\\n\\n\u8FC1\u79FB\u524D\uFF1A\\n\\n```java\\nimport cn.idev.excel.FastExcel;\\nimport cn.idev.excel.annotation.ExcelProperty;\\nimport cn.idev.excel.read.listener.ReadListener;\\n\\nFastExcel.write(outputStream, BookData.class)\\n        .sheet(\\"Sheet1\\")\\n        .doWrite(data());\\n```\\n\\n\u8FC1\u79FB\u540E\uFF1A\\n\\n```java\\nimport org.apache.fesod.sheet.FesodSheet;\\nimport org.apache.fesod.sheet.annotation.ExcelProperty;\\nimport org.apache.fesod.sheet.read.listener.ReadListener;\\n\\nFesodSheet.write(outputStream, BookData.class)\\n        .sheet(\\"Sheet1\\")\\n        .doWrite(data());\\n```\\n\\n## \u53C2\u8003\\n\\n- Apache Fesod (Incubating) \u5B98\u65B9\u8FC1\u79FB\u6307\u5357\uFF1A[https://fesod.apache.org/docs/migration/from-fastexcel/](https://fesod.apache.org/docs/migration/from-fastexcel/)\\n- OpenRewrite \u5B98\u65B9\u6587\u6863\uFF1A[https://docs.openrewrite.org/](https://docs.openrewrite.org/)\\n- OpenRewrite Recipe \u53C2\u8003\uFF1A[https://docs.openrewrite.org/recipes](https://docs.openrewrite.org/recipes)"},{"id":"/2026/04/29/from-user-to-committer","metadata":{"permalink":"/zh-cn/blog/2026/04/29/from-user-to-committer","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2026-04-29-from-user-to-committer.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2026-04-29-from-user-to-committer.md","title":"\u4ECE\u4F7F\u7528\u8005\u5230 Committer","description":"\u4ECE\u4F7F\u7528\u8005\u5230 Committer","date":"2026-04-29T00:00:00.000Z","tags":[{"inline":true,"label":"opensource","permalink":"/zh-cn/blog/tags/opensource"},{"inline":true,"label":"apache","permalink":"/zh-cn/blog/tags/apache"},{"inline":true,"label":"committer","permalink":"/zh-cn/blog/tags/committer"},{"inline":true,"label":"fesod","permalink":"/zh-cn/blog/tags/fesod"}],"hasTruncateMarker":true,"authors":[{"name":"Jing Yang","url":"https://github.com/bengbengbalabalabeng","socials":{"github":"https://github.com/bengbengbalabalabeng"},"imageURL":"data:image/png;base64,","key":"bengbengbalabalabeng","page":null}],"frontMatter":{"title":"\u4ECE\u4F7F\u7528\u8005\u5230 Committer","description":"\u4ECE\u4F7F\u7528\u8005\u5230 Committer","authors":["bengbengbalabalabeng"],"tags":["opensource","apache","committer","fesod"]},"unlisted":false,"prevItem":{"title":"\u4F7F\u7528 OpenRewrite \u4ECE FastExcel 1.3.0 \u81EA\u52A8\u8FC1\u79FB\u5230 Apache Fesod (Incubating)","permalink":"/zh-cn/blog/2026/05/07/migration-from-fastexcel-with-openrewrite"},"nextItem":{"title":"Apache Fesod (Incubating) 2.0.1-incubating \u6B63\u5F0F\u53D1\u5E03","permalink":"/zh-cn/blog/2026/02/27/apache-fesod-2-0-1-incubating-released"}},"content":"\x3c!--\\n- Licensed to the Apache Software Foundation (ASF) under one or more\\n- contributor license agreements.  See the NOTICE file distributed with\\n- this work for additional information regarding copyright ownership.\\n- The ASF licenses this file to You under the Apache License, Version 2.0\\n- (the \\"License\\"); you may not use this file except in compliance with\\n- the License.  You may obtain a copy of the License at\\n-\\n-   http://www.apache.org/licenses/LICENSE-2.0\\n-\\n- Unless required by applicable law or agreed to in writing, software\\n- distributed under the License is distributed on an \\"AS IS\\" BASIS,\\n- WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n- See the License for the specific language governing permissions and\\n- limitations under the License.\\n--\x3e\\n\\n![Apache Fesod New Committer](/img/blog/apache-fesod-new-committer.svg)\\n\\n\u5927\u5BB6\u597D\uFF0C\u6211\u662F `bengbengbalabalabeng`\u3002\u975E\u5E38\u8363\u5E78\u80FD\u5728\u8FD9\u91CC\u4E0E\u5927\u5BB6\u5206\u4EAB\u6211\u7684\u559C\u60A6\uFF1A\u8FD1\u671F\u6211\u6B63\u5F0F\u53D7\u9080\u6210\u4E3A\u4E86 **Apache Fesod (Incubating)** \u9879\u76EE\u7684 Committer\u3002\\n\\n\u4ECE\u6700\u521D\u7684\u666E\u901A\u7528\u6237\uFF0C\u5230\u63D0\u4EA4\u7B2C\u4E00\u4E2A `Bugfix`\uFF0C\u518D\u5230\u6DF1\u5165\u53C2\u4E0E\u4EE3\u7801\u8D21\u732E\u3001\u6587\u6863\u5B8C\u5584\u4E0E\u793E\u533A\u7B54\u7591\uFF0C\u8FD9\u4E00\u8DEF\u8D70\u6765\u6536\u83B7\u9887\u4E30\u3002\u501F\u6B64\u673A\u4F1A\uFF0C\u6211\u60F3\u8BB0\u5F55\u4E00\u4E0B\u8FD9\u6BB5\u5F00\u6E90\u4E4B\u65C5\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n## \u521D\u8BC6 Apache Fesod (Incubating)\\n\\n\u4F5C\u4E3A\u4E00\u540D Java \u5F00\u53D1\u8005\uFF0C\u6211\u5728\u5DE5\u4F5C\u4E2D\u7ECF\u5E38\u9762\u4E34\u5904\u7406\u590D\u6742 Excel \u6587\u4EF6\u7684\u9700\u6C42\u3002\u5728\u5BFB\u627E\u9AD8\u6548\u89E3\u51B3\u65B9\u6848\u7684\u8FC7\u7A0B\u4E2D\uFF0C\u6211\u63A5\u89E6\u5230\u4E86 FastExcel\u3002\u5B83\u6781\u5927\u5730\u7B80\u5316\u4E86\u6211\u5728\u65E5\u5E38\u5F00\u53D1\u4E2D\u5904\u7406 Excel \u6570\u636E\u7684\u590D\u6742\u5EA6\u3002\\n\u540E\u6765\uFF0C\u4E00\u4E2A\u4EE4\u4EBA\u632F\u594B\u7684\u6D88\u606F\u4F20\u6765\uFF1AFastExcel \u5BA3\u5E03\u5C06\u5176\u6350\u8D60\u7ED9 Apache \u8F6F\u4EF6\u57FA\u91D1\u4F1A\uFF0C\u6B63\u5F0F\u8FDB\u5165\u5B75\u5316\u5668\u5E76\u66F4\u540D\u4E3A Apache Fesod (Incubating)\u3002\u90A3\u4E00\u523B\uFF0C\u6211\u611F\u89C9\u8FD9\u4E2A\u9879\u76EE\u7684\u6D3B\u529B\u88AB\u63D0\u5347\u5230\u4E86\u4E00\u4E2A\u5168\u65B0\u7684\u9AD8\u5EA6\u3002\\n\u5B83\u65E2\u62E5\u6709 FastExcel \u65F6\u4EE3\u79EF\u7D2F\u7684\u5E9E\u5927\u7528\u6237\u57FA\u7840\u4E0E\u5F71\u54CD\u529B\uFF0C\u53C8\u5C55\u73B0\u51FA\u4E86\u5728 Apache \u5F00\u6E90\u571F\u58E4\u4E2D\u672A\u88AB\u5B8C\u5168\u5F00\u53D1\u7684\u5DE8\u5927\u6F5C\u529B\u3002\u8FD9\u79CD\u4F18\u79C0\u7684\u5DE5\u5177\u5728\u66F4\u5927\u7684\u5E73\u53F0\u4E0A\u7115\u53D1\u201C\u65B0\u751F\u673A\u201D\u7684\u5947\u5999\u7ED3\u5408\u6DF1\u6DF1\u5438\u5F15\u4E86\u6211\u3002\\n\\n\u7136\u540E\uFF0C\u6211\u4FBF\u5F00\u59CB\u5173\u6CE8\u793E\u533A\u7684\u52A8\u6001\uFF0C\u4ECE\u9ED8\u9ED8\u6F5C\u6C34\u5230\u5728 Issues \u91CC\u53C2\u4E0E\u5927\u5BB6\u7684\u8BA8\u8BBA\uFF0C\u518D\u5230\u63D0\u4EA4\u7B2C\u4E00\u4E2A PR([#668](https://github.com/apache/fesod/pull/668))\u3002\\n\\n## \u6211\u7684\u8D21\u732E\\n\\n\u6709\u4E86\u7B2C\u4E00\u6B21\u5408\u5E76 PR \u7684\u7ECF\u5386\u540E\uFF0C\u6211\u4E0D\u518D\u5C40\u9650\u4E8E\u5355\u4E00\u7684\u62A5\u9519\u4FEE\u590D\uFF0C\u800C\u662F\u5C1D\u8BD5\u4ECE\u6574\u4F53\u53BB\u5BA1\u89C6\u9879\u76EE\u3002\u4E3B\u8981\u662F\u8D21\u732E\u65B9\u5411\u5982\u4E0B\uFF1A\\n\\n- **\u6587\u6863\u4F53\u7CFB\u5EFA\u8BBE**\\n- **Bug \u4FEE\u590D**\\n- **\u6D4B\u8BD5\u4F53\u7CFB\u5B8C\u5584**\\n- **\u529F\u80FD\u589E\u5F3A**\\n- **\u793E\u533A\u4E92\u52A8**\\n\\n## \u6211\u7684\u6536\u83B7\\n\\n\u5728\u53C2\u4E0E Apache Fesod (Incubating) \u7684\u8FC7\u7A0B\u4E2D\uFF0C\u6211\u6DF1\u523B\u4F53\u4F1A\u5230\uFF1A\\n\\n- **\u5F00\u6E90\u4E0D\u53EA\u662F\u5199\u4EE3\u7801\u8FD8\u6709\u534F\u4F5C\u3002** Issue\u3001PR\u3001Review\u3001\u8BA8\u8BBA\uFF0C\u6BCF\u4E00\u6B65\u90FD\u9700\u8981\u6E05\u6670\u6C9F\u901A\u4E0E\u8010\u5FC3\u3002\\n- **\u5C0F\u8D21\u732E\u4E5F\u80FD\u4EA7\u751F\u5DE8\u5927\u5F71\u54CD\u3002** \u4E00\u4E2A typo \u4FEE\u590D\u3001\u4E00\u4E2A\u793A\u4F8B\u8865\u5145\uFF0C\u90FD\u53EF\u80FD\u5E2E\u52A9\u6210\u5343\u4E0A\u4E07\u7684\u7528\u6237\u3002\\n- **\u793E\u533A\u7684\u529B\u91CF\u8FDC\u5927\u4E8E\u4E2A\u4EBA\u3002** \u6BCF\u4E00\u6B21\u8BA8\u8BBA\u3001\u6BCF\u4E00\u6B21\u5171\u8BC6\uFF0C\u90FD\u8BA9\u9879\u76EE\u53D8\u5F97\u66F4\u597D\u3002\\n\\n## \u7ED3\u8BED\\n\\n\u6210\u4E3A Committer \u7EDD\u4E0D\u662F\u7EC8\u70B9\uFF0C\u800C\u662F\u4E00\u4E2A\u5168\u65B0\u7684\u8D77\u70B9\u3002\u5B83\u610F\u5473\u7740\u66F4\u591A\u7684\u8D23\u4EFB\u548C\u66F4\u9AD8\u7684\u8981\u6C42\u3002\u6211\u5F88\u671F\u5F85\u4E0E\u793E\u533A\u4E00\u8D77\u628A Apache Fesod (Incubating) \u5EFA\u8BBE\u5F97\u66F4\u597D\u3002"},{"id":"/2026/02/27/apache-fesod-2-0-1-incubating-released","metadata":{"permalink":"/zh-cn/blog/2026/02/27/apache-fesod-2-0-1-incubating-released","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2026-02-27-apache-fesod-2-0-1-incubating-released.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2026-02-27-apache-fesod-2-0-1-incubating-released.md","title":"Apache Fesod (Incubating) 2.0.1-incubating \u6B63\u5F0F\u53D1\u5E03","description":"Apache Fesod (Incubating) \u793E\u533A\u6B23\u7136\u5BA3\u5E03\uFF0CApache Fesod (Incubating) 2.0.1-incubating \u7248\u672C\u6B63\u5F0F\u53D1\u5E03\uFF01","date":"2026-02-27T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/zh-cn/blog/tags/announcement"},{"inline":true,"label":"release","permalink":"/zh-cn/blog/tags/release"}],"hasTruncateMarker":true,"authors":[{"name":"Shuxin Pan","url":"https://github.com/psxjoy","socials":{"github":"https://github.com/psxjoy"},"imageURL":"data:image/png;base64,","key":"psxjoy","page":null}],"frontMatter":{"title":"Apache Fesod (Incubating) 2.0.1-incubating \u6B63\u5F0F\u53D1\u5E03","description":"Apache Fesod (Incubating) \u793E\u533A\u6B23\u7136\u5BA3\u5E03\uFF0CApache Fesod (Incubating) 2.0.1-incubating \u7248\u672C\u6B63\u5F0F\u53D1\u5E03\uFF01","authors":["psxjoy"],"tags":["announcement","release"]},"unlisted":false,"prevItem":{"title":"\u4ECE\u4F7F\u7528\u8005\u5230 Committer","permalink":"/zh-cn/blog/2026/04/29/from-user-to-committer"},"nextItem":{"title":"\u6B22\u8FCE Apache Fesod \u65B0\u664B Committer","permalink":"/zh-cn/blog/2026/02/27/welcome-new-committer"}},"content":"\x3c!--\\n- Licensed to the Apache Software Foundation (ASF) under one or more\\n- contributor license agreements.  See the NOTICE file distributed with\\n- this work for additional information regarding copyright ownership.\\n- The ASF licenses this file to You under the Apache License, Version 2.0\\n- (the \\"License\\"); you may not use this file except in compliance with\\n- the License.  You may obtain a copy of the License at\\n-\\n-   http://www.apache.org/licenses/LICENSE-2.0\\n-\\n- Unless required by applicable law or agreed to in writing, software\\n- distributed under the License is distributed on an \\"AS IS\\" BASIS,\\n- WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n- See the License for the specific language governing permissions and\\n- limitations under the License.\\n--\x3e\\n\\n**2026\u5E742\u6708** \u2014\u2014 Apache Fesod (Incubating) \u793E\u533A\u6B23\u7136\u5BA3\u5E03\uFF0C**Apache Fesod (Incubating) 2.0.1-incubating \u7248\u672C\u6B63\u5F0F\u53D1\u5E03\uFF01**\\n\\n\u8FD9\u4E0D\u4EC5\u662F\u4E00\u4E2A\u6280\u672F\u7248\u672C\u7684\u8FED\u4EE3\uFF0C\u66F4\u662F Fesod \u9879\u76EE\u81EA\u52A0\u5165 **Apache \u8F6F\u4EF6\u57FA\u91D1\u4F1A (ASF)** \u5B75\u5316\u5668\u4EE5\u6765\u7684**\u9996\u4E2A\u6B63\u5F0F\u53D1\u5E03\u7248\u672C**\u3002\u5728\u8FC7\u53BB\u7684\u51E0\u4E2A\u6708\u4E2D\uFF0C\u793E\u533A\u6210\u5458\u5171\u540C\u5B8C\u6210\u4E86\u5927\u91CF\u7684\u5408\u89C4\u6027\u6539\u9020\u3001\u67B6\u6784\u91CD\u6784\u4EE5\u53CA\u529F\u80FD\u589E\u5F3A\uFF0C\u6807\u5FD7\u7740 Fesod \u5DF2\u7ECF\u5B8C\u5168\u51C6\u5907\u597D\u5728 ASF \u89C4\u8303\u4E0B\u5F00\u542F\u9AD8\u6027\u80FD Excel \u5904\u7406\u7684\u65B0\u7BC7\u7AE0\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u91CC\u7A0B\u7891\u610F\u4E49\uFF1A\u9996\u4E2A\u6B63\u5F0F\u7684 ASF Release\\n\\n\u4F5C\u4E3A\u8FDB\u5165\u5B75\u5316\u5668\u540E\u7684\u201C\u5904\u5B50\u79C0\u201D\uFF0C2.0.1 \u7248\u672C\u5728 **Apache Way\uFF08Apache \u4E4B\u9053\uFF09** \u65B9\u9762\u53D6\u5F97\u4E86\u51B3\u5B9A\u6027\u8FDB\u5C55\uFF1A\\n\\n* **\u5168\u9762\u66F4\u540D\u4E0E\u5408\u89C4\uFF1A** \u6211\u4EEC\u5B8C\u6210\u4E86\u4ECE `FastExcel` \u5230 `Fesod` \u7684\u5168\u9762\u91CD\u547D\u540D\uFF08\u5305\u62EC\u5305\u540D\u3001\u7C7B\u540D\u53CA\u6587\u6863\uFF09\uFF0C\u786E\u4FDD\u54C1\u724C\u5B8C\u5168\u53D7 ASF \u4FDD\u62A4\u3002\\n* **\u5408\u89C4\u6027\u8865\u5168\uFF1A** \u5F15\u5165\u4E86 `DISCLAIMER`\u3001`NOTICE` \u4EE5\u53CA `support` \u6A21\u5757\uFF0C\u5E76\u901A\u8FC7 Spotless \u5B9E\u73B0\u4E86\u81EA\u52A8\u5316\u7684 License Header \u7BA1\u7406\uFF0C\u5B8C\u5168\u7B26\u5408 ASF \u7684\u653F\u7B56\u8981\u6C42\u3002\\n* **\u793E\u533A\u6CBB\u7406\uFF1A** \u6240\u6709\u7684\u4EE3\u7801\u5408\u5E76\u4E0E\u7248\u672C\u53D1\u5E03\u5747\u7ECF\u8FC7\u4E86\u793E\u533A\u6295\u7968\u4E0E\u90AE\u4EF6\u5217\u8868\u8BA8\u8BBA\uFF0C\u4F53\u73B0\u4E86\u516C\u5F00\u3001\u900F\u660E\u7684\u6CBB\u7406\u539F\u5219\u3002\\n\\n## \u7248\u672C\u6838\u5FC3\u4EAE\u70B9\\n\\n### 1. \u67B6\u6784\u6DF1\u5EA6\u91CD\u6784\\n\\n\u4E3A\u4E86\u652F\u6301\u66F4\u957F\u8FDC\u7684\u53D1\u5C55\uFF0C\u6211\u4EEC\u5BF9\u9879\u76EE\u7ED3\u6784\u8FDB\u884C\u4E86\u5927\u89C4\u6A21\u4F18\u5316\uFF1A\\n\\n* **\u591A\u6A21\u5757\u5316\uFF08Multi-module\uFF09\uFF1A** \u5F15\u5165\u4E86\u591A\u6A21\u5757\u67B6\u6784\uFF0C\u4F7F\u9879\u76EE\u5C42\u6B21\u66F4\u6E05\u6670\uFF0C\u4F9D\u8D56\u7BA1\u7406\u66F4\u7CBE\u7EC6\u3002\\n* **\u5206\u53D1\u589E\u5F3A\uFF1A** \u65B0\u589E `fesod-distribution` \u6A21\u5757\uFF0C\u89C4\u8303\u4E86\u5206\u53D1\u5305\u7684\u63CF\u8FF0\u4E0E\u6784\u5EFA\u3002\\n* **JDK 25 \u652F\u6301\uFF1A** \u7D27\u8DDF Java \u751F\u6001\uFF0C\u6B63\u5F0F\u589E\u52A0\u4E86\u5BF9 **JDK 25** \u7684\u517C\u5BB9\u4E0E\u652F\u6301\u3002\\n\\n### 2. \u529F\u80FD\u7279\u6027 (Features)\\n\\n\u672C\u6B21\u53D1\u5E03\u5F15\u5165\u4E86\u591A\u9879\u5B9E\u7528\u65B0\u529F\u80FD\uFF0C\u8FDB\u4E00\u6B65\u589E\u5F3A\u4E86 Excel \u5904\u7406\u7684\u7075\u6D3B\u6027\uFF1A\\n\\n* **Excel \u5904\u7406\u589E\u5F3A\uFF1A** \u5728 `SheetWriteHandler` \u4E2D\u65B0\u589E\u4E86 `afterSheetDispose` \u751F\u547D\u5468\u671F\u65B9\u6CD5\uFF0C\u5E76\u5F15\u5165\u4E86\u5168\u65B0\u7684**\u8868\u5934\u5408\u5E76\u7B56\u7565\uFF08Header Merge Strategy\uFF09**\u3002\\n* **\u8001\u7248\u672C\u517C\u5BB9\uFF1A** \u4F18\u96C5\u5730\u5904\u7406\u4E86\u6781\u8001\u7248\u672C\u7684 Excel BIFF \u683C\u5F0F\uFF0C\u907F\u514D\u8FD0\u884C\u5D29\u6E83\u3002\\n* **\u7075\u6D3B\u63A7\u5236\uFF1A** \u65B0\u589E `autoStrip` \u53C2\u6570\uFF0C\u5E76\u5728 `Workbook` \u5E38\u91CF\u4E2D\u5F15\u5165\u4E86\u6700\u5927 Sheet \u540D\u79F0\u957F\u5EA6\u6821\u9A8C\u3002\\n* **\u7F51\u7AD9\u4F53\u9A8C\uFF1A** \u5B98\u65B9\u6587\u6863\u65B0\u589E\u4E86\u672C\u5730\u641C\u7D22\u529F\u80FD\u53CA Matomo \u7EDF\u8BA1\u63D2\u4EF6\uFF0C\u5E76\u4F18\u5316\u4E86\u79FB\u52A8\u7AEF\u5C55\u793A\u3002\\n\\n### 3. \u7A33\u5B9A\u6027\u4E0E\u5065\u58EE\u6027 (Stability)\\n\\n\u6211\u4EEC\u6295\u5165\u4E86\u5927\u91CF\u7CBE\u529B\u5728\u8D28\u91CF\u4FDD\u969C\u4E0A\uFF1A\\n\\n* **\u6A21\u7CCA\u6D4B\u8BD5 (Fuzz Testing)\uFF1A** \u4E3A Excel \u8BFB\u53D6\u589E\u52A0\u4E86\u6BCF\u65E5\u6A21\u7CCA\u6D4B\u8BD5\u4EFB\u52A1\uFF0C\u80FD\u66F4\u65E9\u53D1\u73B0\u5904\u7406\u5F02\u5E38\u6587\u4EF6\u65F6\u7684\u6F5C\u5728\u5D29\u6E83\u3002\\n* **\u4F9D\u8D56\u5B89\u5168\uFF1A** \u5347\u7EA7\u4E86 Spring-core\u3001Logback\u3001Fastjson2 \u4EE5\u53CA POI\uFF08\u5347\u7EA7\u81F3 5.5.1\uFF09\u7B49\u6838\u5FC3\u4F9D\u8D56\uFF0C\u4FEE\u590D\u4E86\u591A\u9879\u5DF2\u77E5\u6F0F\u6D1E\u3002\\n* **CI/CD \u4F18\u5316\uFF1A** \u5F15\u5165\u4E86 Netlify \u9884\u89C8\u90E8\u7F72\u548C\u81EA\u52A8\u5173\u95ED\u8FC7\u671F Issue \u7684\u5DE5\u4F5C\u6D41\uFF0C\u663E\u8457\u63D0\u5347\u4E86\u793E\u533A\u534F\u4F5C\u6548\u7387\u3002\\n\\n## \u5173\u952E\u53D8\u66F4\u6982\u89C8\\n\\n### **\u65B0\u529F\u80FD (Feature)**\\n\\n* `SheetWriteHandler` \u589E\u52A0 `afterSheetDispose` \u65B9\u6CD5\u3002\\n* \u589E\u52A0 Excel \u5199\u5165\u7684\u8868\u5934\u5408\u5E76\u7B56\u7565\u3002\\n* \u589E\u52A0 GitHub Actions \u7684 Netlify \u9884\u89C8\u90E8\u7F72\u652F\u6301\u3002\\n* \u589E\u52A0 `docusaurus-search-local` \u63D2\u4EF6\u4EE5\u652F\u6301\u5B98\u7F51\u641C\u7D22\u3002\\n\\n### **\u4FEE\u590D (Bugfix)**\\n\\n* \u4FEE\u590D `WriteSheetWorkbookWriteHandler` \u7C7B\u4E2D\u7684 NPE \u5F02\u5E38\u3002\\n* \u4FEE\u590D\u6587\u6863\u4E2D\u9519\u8BEF\u7684\u793A\u4F8B\u4EE3\u7801\u53CA\u8FC7\u671F\u7684\u94FE\u63A5\u3002\\n* \u5347\u7EA7\u4F9D\u8D56\u4EE5\u4FEE\u590D\u6F0F\u6D1E\u544A\u8B66\uFF0C\u5E76\u66F4\u65B0 import \u8BED\u53E5\u4EE5\u4F7F\u7528 shaded \u540E\u7684 cglib \u62A5\u540D\u3002\\n\\n### **\u91CD\u6784 (Refactor)**\\n\\n* \u5C06\u9879\u76EE\u91CD\u547D\u540D\u4E3A Fesod/FesodSheet\uFF0C\u5E76\u66F4\u65B0\u5305\u7ED3\u6784\u4EE5\u7B26\u5408 Apache \u547D\u540D\u89C4\u8303\u3002\\n* \u5F15\u5165 Spotless \u81EA\u52A8\u7BA1\u7406 License Header\u3002\\n* \u79FB\u9664\u8FC7\u671F\u4E14\u4E0D\u6B63\u786E\u7684 `@since` \u6807\u7B7E\uFF0C\u7CBE\u7B80\u6838\u5FC3\u7C7B\u3002\\n\\n> \u8BE6\u7EC6\u7684\u53D8\u66F4\u5217\u8868\u8BF7\u53C2\u8003\uFF1A[GitHub Release Notes](https://github.com/apache/fesod/releases/tag/2.0.1-incubating)\\n\\n## \u81F4\u8C22\\n\\n\u201C\u793E\u533A\u4F18\u4E8E\u4EE3\u7801\u201D\u662F Apache \u7684\u6838\u5FC3\u7406\u5FF5\u3002\u611F\u8C22\u6240\u6709\u4E3A\u6B64\u7248\u672C\u505A\u51FA\u8D21\u732E\u7684\u5F00\u53D1\u8005\u3001Mentors \u4EE5\u53CA\u793E\u533A\u6210\u5458\u3002\\n\\n### \u65B0\u8D21\u732E\u8005 (New Contributors)\\n\\n\u6211\u4EEC\u8981\u7279\u522B\u6B22\u8FCE\u5E76\u611F\u8C22\u5728\u8BE5\u7248\u672C\u4E2D\u505A\u51FA\u9996\u6B21\u8D21\u732E\u7684 **14 \u4F4D\u65B0\u6210\u5458**\uFF1A\\n\\n> @X-qinghai, @ngocnhan-tran1996, @YIminta, @jounghu, @wlgusqkr, @gaushon, @GOODBOY008, @ongdisheng, @harshasiddartha, @pjfanning, @liugddx, @hezhangjian, @bengbengbalabalabeng\\n\\n\u7279\u522B\u611F\u8C22 **@delei, @psxjoy, @alaahong, @ongdisheng, @GOODBOY008** \u4EE5\u53CA\u6240\u6709\u5728 GitHub \u4E0A\u63D0\u4EA4 PR \u548C\u5EFA\u8BAE\u7684\u670B\u53CB\u4EEC\u3002\u6B63\u662F\u7531\u4E8E\u4F60\u4EEC\u5728\u91CD\u547D\u540D\u3001\u5408\u89C4\u6027\u68C0\u67E5\u3001CI \u4F18\u5316\u4EE5\u53CA\u6838\u5FC3\u529F\u80FD\u6539\u8FDB\u4E0A\u7684\u4E0D\u61C8\u52AA\u529B\uFF0C\u624D\u4FC3\u6210\u4E86 Fesod \u5728 Apache \u7684\u5B8C\u7F8E\u9996\u79C0\u3002\\n\\n## \u5982\u4F55\u83B7\u53D6\\n\\n\u4F60\u53EF\u4EE5\u901A\u8FC7\u4EE5\u4E0B\u6E20\u9053\u4E0B\u8F7D\u5E76\u4F53\u9A8C\u5168\u65B0\u7684 Apache Fesod (Incubating) \uFF1A\\n\\n* **\u5B98\u65B9\u7F51\u7AD9\uFF1A** [https://fesod.apache.org/](https://fesod.apache.org/)\\n* **\u6E90\u7801\u4ED3\u5E93\uFF1A** [https://github.com/apache/fesod](https://github.com/apache/fesod)\\n* **Maven \u5750\u6807\uFF1A**\\n\\n```xml\\n<dependency>\\n    <groupId>org.apache.fesod</groupId>\\n    <artifactId>fesod</artifactId>\\n    <version>2.0.1-incubating</version>\\n</dependency>\\n```\\n\\n**\u6B22\u8FCE\u52A0\u5165\u6211\u4EEC\uFF01**\\nApache Fesod (Incubating) \u793E\u533A\u59CB\u7EC8\u5BF9\u5F00\u53D1\u8005\u4FDD\u6301\u5F00\u653E\u3002\u4F60\u53EF\u4EE5\u901A\u8FC7\u8BA2\u9605\u90AE\u4EF6\u5217\u8868 `dev@fesod.apache.org` \u6216\u5728 GitHub \u4E0A\u63D0\u4EA4 Issue \u4E0E\u6211\u4EEC\u4EA4\u6D41\u3002\\n\\n\u8BA9\u6211\u4EEC\u5171\u540C\u671F\u5F85 Fesod \u5728 Apache \u5B75\u5316\u5668\u4E2D\u8301\u58EE\u6210\u957F\uFF01"},{"id":"/2026/02/27/welcome-new-committer","metadata":{"permalink":"/zh-cn/blog/2026/02/27/welcome-new-committer","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2026-02-27-welcome-new-committer.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2026-02-27-welcome-new-committer.md","title":"\u6B22\u8FCE Apache Fesod \u65B0\u664B Committer","description":"\u6B22\u8FCE Apache Fesod \u65B0\u664B Committer","date":"2026-02-27T00:00:00.000Z","tags":[{"inline":true,"label":"opensource","permalink":"/zh-cn/blog/tags/opensource"},{"inline":true,"label":"apache","permalink":"/zh-cn/blog/tags/apache"},{"inline":true,"label":"committer","permalink":"/zh-cn/blog/tags/committer"},{"inline":true,"label":"fesod","permalink":"/zh-cn/blog/tags/fesod"}],"hasTruncateMarker":true,"authors":[{"name":"Zhongqiang Gong","url":"https://github.com/GOODBOY008","socials":{"github":"https://github.com/GOODBOY008"},"imageURL":"data:image/png;base64,","key":"GOODBOY008","page":null}],"frontMatter":{"title":"\u6B22\u8FCE Apache Fesod \u65B0\u664B Committer","description":"\u6B22\u8FCE Apache Fesod \u65B0\u664B Committer","authors":["GOODBOY008"],"tags":["opensource","apache","committer","fesod"]},"unlisted":false,"prevItem":{"title":"Apache Fesod (Incubating) 2.0.1-incubating \u6B63\u5F0F\u53D1\u5E03","permalink":"/zh-cn/blog/2026/02/27/apache-fesod-2-0-1-incubating-released"},"nextItem":{"title":"\u5B98\u5BA3! Fesod \u6210\u529F\u8FDB\u5165 Apache \u5B75\u5316\u5668","permalink":"/zh-cn/blog/2025/09/17/fesod-entered-apache-incubator"}},"content":"\x3c!--\\n- Licensed to the Apache Software Foundation (ASF) under one or more\\n- contributor license agreements.  See the NOTICE file distributed with\\n- this work for additional information regarding copyright ownership.\\n- The ASF licenses this file to You under the Apache License, Version 2.0\\n- (the \\"License\\"); you may not use this file except in compliance with\\n- the License.  You may obtain a copy of the License at\\n-\\n-   http://www.apache.org/licenses/LICENSE-2.0\\n-\\n- Unless required by applicable law or agreed to in writing, software\\n- distributed under the License is distributed on an \\"AS IS\\" BASIS,\\n- WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n- See the License for the specific language governing permissions and\\n- limitations under the License.\\n--\x3e\\n\\n![Apache Fesod New Committer](/img/blog/apache-fesod-new-committer.svg)\\n\\n> \u5927\u5BB6\u597D\uFF01\u975E\u5E38\u8363\u5E78\u53D7\u5230 Apache Fesod \u793E\u533A\u7684\u9080\u8BF7\uFF0C\u6210\u4E3A\u4E00\u540D Committer\u3002\u5728\u6B64\uFF0C\u6211\u60F3\u4E0E\u5927\u5BB6\u5206\u4EAB\u6211\u7684\u5F00\u6E90\u4E4B\u65C5\u4EE5\u53CA\u4E00\u8DEF\u8D70\u6765\u7684\u7ECF\u5386\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u81EA\u6211\u4ECB\u7ECD\\n\\n\u6211\u53EB\u9F9A\u4E2D\u5F3A\uFF08GitHub: [GOODBOY008](https://github.com/GOODBOY008)\uFF09\uFF0C\u662F\u4E00\u540D\u70ED\u7231\u5F00\u6E90\u548C Java \u751F\u6001\u7684\u8F6F\u4EF6\u5DE5\u7A0B\u5E08\uFF0C\u540C\u65F6\u4E5F\u662F **Apache Flink Committer** \u548C **Apache StreamPark Committer**\u3002\\n\\n## \u4E0E Apache Fesod \u7684\u521D\u9047\\n\\n\u6211\u7B2C\u4E00\u6B21\u63A5\u89E6 Fesod \u662F\u5728 **2025 \u5E74 9 \u6708**\uFF0C\u5F7C\u65F6\u9879\u76EE\u521A\u521A\u8FDB\u5165 Apache \u5B75\u5316\u9636\u6BB5\u3002\u4F5C\u4E3A\u4E00\u4E2A\u88AB\u5E7F\u6CDB\u4F7F\u7528\u7684 Java \u7535\u5B50\u8868\u683C\u5904\u7406\u5E93\uFF0C\u5B83\u5DF2\u7ECF\u62E5\u6709\u4E86\u575A\u5B9E\u7684\u7528\u6237\u57FA\u7840\u2014\u2014\u800C\u5728 Apache \u6CBB\u7406\u4E0B\uFF0C\u9879\u76EE\u66F4\u662F\u5145\u6EE1\u4E86\u6210\u957F\u7A7A\u95F4\u3002\u8FD9\u79CD\u73B0\u5B9E\u5F71\u54CD\u529B\u4E0E\u672A\u88AB\u5F00\u53D1\u7684\u6F5C\u529B\u7684\u7ED3\u5408\u6DF1\u6DF1\u5438\u5F15\u4E86\u6211\uFF0C\u8BA9\u6211\u660E\u786E\u4E86\u8981\u53C2\u4E0E\u5851\u9020\u5176\u5F00\u6E90\u672A\u6765\u7684\u51B3\u5FC3\u3002\\n\\n## \u6211\u7684\u8D21\u732E\\n\\n\u52A0\u5165\u793E\u533A\u4EE5\u6765\uFF0C\u6211\u7684\u8D21\u732E\u6DB5\u76D6\u4E86\u516D\u4E2A\u5173\u952E\u9886\u57DF\uFF1A\\n\\n- **\u54C1\u724C\u8FC1\u79FB** \u2014 \u63A8\u52A8\u4E86\u4ECE FastExcel \u5230 FesodSheet \u7684\u7CFB\u7EDF\u6027\u8FC1\u79FB\uFF0C\u8986\u76D6\u6838\u5FC3\u7C7B\u3001\u6D4B\u8BD5\u4EE3\u7801\u3001\u793A\u4F8B\u7A0B\u5E8F\u53CA\u9762\u5411\u7528\u6237\u7684\u9519\u8BEF\u63D0\u793A\u4FE1\u606F\u3002\\n- **\u4EE3\u7801\u8D28\u91CF** \u2014 \u6D88\u9664\u4E86\u91CD\u590D\u7684\u5DE5\u5177\u7C7B\uFF0C\u89C4\u8303\u4E86 Lombok \u7684\u4F7F\u7528\uFF0C\u4F18\u5316\u4E86\u6D4B\u8BD5\u65AD\u8A00\u6A21\u5F0F\uFF0C\u63D0\u5347\u4E86\u53EF\u7EF4\u62A4\u6027\u3002\\n- **CI/CD** \u2014 \u4E3A GitHub Actions \u5F15\u5165\u4E86\u5E76\u53D1\u63A7\u5236\u3001\u57FA\u4E8E\u8DEF\u5F84\u7684\u8FC7\u6EE4\u548C Fork \u4FDD\u62A4\u673A\u5236\uFF0C\u4F7F\u6D41\u6C34\u7EBF\u66F4\u5FEB\u3001\u66F4\u7ECF\u6D4E\u3002\\n- **\u6587\u6863** \u2014 \u7F16\u5199\u4E86\u4E2D\u82F1\u53CC\u8BED\u8FC1\u79FB\u6307\u5357\uFF0C\u5E76\u4F18\u5316\u4E86\u6587\u6863\u7AD9\u70B9\u7684\u5BFC\u822A\u7ED3\u6784\u3002\\n- **\u6D4B\u8BD5\u4E0E\u6027\u80FD** \u2014 \u5EFA\u7ACB\u4E86\u5171\u4EAB testkit \u57FA\u7840\u8BBE\u65BD\uFF0C\u663E\u8457\u51CF\u5C11\u4E86\u6D4B\u8BD5\u91CD\u590D\u4EE3\u7801\uFF0C\u5E76\u5F15\u5165\u4E86\u57FA\u4E8E JMH \u7684\u57FA\u51C6\u6D4B\u8BD5\u6846\u67B6\u8FDB\u884C\u6027\u80FD\u9A8C\u8BC1\u3002\\n- **\u67B6\u6784** \u2014 \u63D0\u51FA\u5E76\u63A8\u52A8\u4E86\u793A\u4F8B\u6A21\u5757\u91CD\u6784\u3001\u73B0\u4EE3\u5316\u6D4B\u8BD5\u6A21\u5F0F\u4EE5\u53CA\u957F\u671F\u6027\u80FD\u6D4B\u8BD5\u6846\u67B6\u7684\u8BA8\u8BBA\u3002\\n\\n## \u6211\u7684\u6536\u83B7\\n\\n\u53C2\u4E0E Apache \u9879\u76EE\u8BA9\u6211\u5B66\u5230\u4E86\u4E09\u4EF6\u4E8B\uFF1A**\u793E\u533A\u91CD\u4E8E\u4EE3\u7801** \u2014 \u5171\u8BC6\u548C\u900F\u660E\u5EA6\u6BD4\u4EFB\u4F55\u5355\u4E2A PR \u90FD\u91CD\u8981\uFF1B**\u4ECE\u5C0F\u5904\u7740\u624B\uFF0C\u653E\u773C\u5168\u5C40** \u2014 \u6211\u7684\u7B2C\u4E00\u4E2A\u5C0F\u578B CI \u4FEE\u590D\uFF08[#664](https://github.com/apache/fesod/pull/664)\uFF09\u6700\u7EC8\u5F15\u53D1\u4E86\u6DF1\u5C42\u6B21\u7684\u57FA\u7840\u8BBE\u65BD\u6539\u8FDB\uFF1B**\u8D28\u91CF\u7684\u590D\u5229\u6548\u5E94** \u2014 \u6BCF\u4E00\u6B21\u5C0F\u7684\u4EE3\u7801\u6E05\u7406\uFF0C\u65E5\u79EF\u6708\u7D2F\u90FD\u4F1A\u8BA9\u4EE3\u7801\u5E93\u66F4\u52A0\u5065\u5EB7\u3002\\n\\n## \u7ED9\u65B0\u8D21\u732E\u8005\u7684\u5EFA\u8BAE\\n\\n1. **\u8FC8\u51FA\u7B2C\u4E00\u6B65\u3002** \u627E\u4E00\u4E2A \\"good first issue\\" \u5F00\u59CB\u2014\u2014\u8FD9\u5F80\u5F80\u662F\u6700\u96BE\u7684\u4E00\u6B65\u3002\\n2. **\u5148\u8BFB\u540E\u5199\u3002** \u5148\u7406\u89E3\u9879\u76EE\u7684\u67B6\u6784\u548C\u89C4\u8303\uFF0C\u518D\u52A8\u624B\u7F16\u7801\u3002\\n3. **\u5F00\u653E\u6C9F\u901A\u3002** \u6E05\u6670\u7684 Issue \u548C PR \u6BD4\u4EE3\u7801\u672C\u8EAB\u66F4\u80FD\u8D62\u5F97\u4FE1\u4EFB\u3002\\n4. **\u7740\u773C\u957F\u8FDC\u3002** \u63D0\u6848\u3001\u6587\u6863\u548C\u57FA\u7840\u8BBE\u65BD\u7684\u6539\u8FDB\u540C\u6837\u662F\u91CD\u8981\u7684\u8D21\u732E\u3002\\n5. **\u4FDD\u6301\u8010\u5FC3\u3002** \u6301\u4E4B\u4EE5\u6052\u6BD4\u5FEB\u901F\u51B2\u523A\u66F4\u91CD\u8981\u3002\\n\\n## \u5C55\u671B\u672A\u6765\\n\\n\u6210\u4E3A Committer \u662F\u4E00\u4E2A\u65B0\u7684\u8D77\u70B9\u3002\u6211\u5C06\u81F4\u529B\u4E8E\u63D0\u5347 Fesod \u7684\u4EE3\u7801\u8D28\u91CF\u3001\u6307\u5BFC\u65B0\u8D21\u732E\u8005\u3001\u63A8\u8FDB\u57FA\u51C6\u6D4B\u8BD5\u6846\u67B6\u7684\u5EFA\u8BBE\uFF0C\u5E76\u52A9\u529B Fesod \u4ECE Apache \u5B75\u5316\u5668\u6BD5\u4E1A\u3002"},{"id":"/2025/09/17/fesod-entered-apache-incubator","metadata":{"permalink":"/zh-cn/blog/2025/09/17/fesod-entered-apache-incubator","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2025-09-17-fesod-entered-apache-incubator.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2025-09-17-fesod-entered-apache-incubator.md","title":"\u5B98\u5BA3! Fesod \u6210\u529F\u8FDB\u5165 Apache \u5B75\u5316\u5668","description":"Fesod successfully entered Apache Incubator.","date":"2025-09-17T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/zh-cn/blog/tags/announcement"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"\u5B98\u5BA3! Fesod \u6210\u529F\u8FDB\u5165 Apache \u5B75\u5316\u5668","description":"Fesod successfully entered Apache Incubator.","tags":["announcement"]},"unlisted":false,"prevItem":{"title":"\u6B22\u8FCE Apache Fesod \u65B0\u664B Committer","permalink":"/zh-cn/blog/2026/02/27/welcome-new-committer"}},"content":"\x3c!--\\n- Licensed to the Apache Software Foundation (ASF) under one or more\\n- contributor license agreements.  See the NOTICE file distributed with\\n- this work for additional information regarding copyright ownership.\\n- The ASF licenses this file to You under the Apache License, Version 2.0\\n- (the \\"License\\"); you may not use this file except in compliance with\\n- the License.  You may obtain a copy of the License at\\n-\\n-   http://www.apache.org/licenses/LICENSE-2.0\\n-\\n- Unless required by applicable law or agreed to in writing, software\\n- distributed under the License is distributed on an \\"AS IS\\" BASIS,\\n- WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n- See the License for the specific language governing permissions and\\n- limitations under the License.\\n--\x3e\\n\\n\u5317\u4EAC\u65F6\u95F42025\u5E7409\u670817\u65E5\uFF0C[Fesod](https://github.com/apache/fesod)\\n\u6B63\u5F0F\u987A\u5229\u901A\u8FC7 Apache \u57FA\u91D1\u4F1A\u5B75\u5316\u5668\u7684\u6295\u7968\u51B3\u8BAE\uFF0C\u6839\u636E Apache\\n\u57FA\u91D1\u4F1A[\u90AE\u4EF6\u5217\u8868](https://lists.apache.org/thread/k744v8ff22mom3bplqkjnc2qvtksj59f)\u663E\u793A\uFF0C\u6700\u7EC8\u4EE5 9\\n\u4E2A\u7EA6\u675F\u6027\u6295\u7968 (binding votes) \uFF0C\u65E0\u5F03\u6743\u548C\u53CD\u5BF9\u7968\u901A\u8FC7\u63A5\u53D7 Fesod \u52A0\u5165 Apache\\n\u5B75\u5316\u5668\u51B3\u8BAE\u3002\u6B63\u5F0F\u6210\u4E3A\u4E86\u5168\u7403\u6700\u5927\u7684\u5F00\u6E90\u57FA\u91D1\u4F1A [Apache \u8F6F\u4EF6\u57FA\u91D1\u4F1A](https://www.apache.org/) \u7684\u5B75\u5316\u9879\u76EE\u30022025\u5E7409\u670825\u65E5\uFF0CFesod\\n\u4ED3\u5E93\u6B63\u5F0F\u8FC1\u79FB\u81F3 Apache \u8F6F\u4EF6\u57FA\u91D1\u4F1A\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\nFesod \u539F\u540D [FastExcel](https://github.com/fast-excel), \u4E8E 2024 \u5E74 10 \u6708\u5728 GitHub\\n\u6B63\u5F0F\u5F00\u6E90\uFF0C\u7ECF\u8FC7\u793E\u533A\u5C0F\u4F19\u4F34\u4EEC\u7684\u4E0D\u95F4\u65AD\u9879\u76EE\u7EF4\u62A4\u8FED\u4EE3\uFF0C\u6301\u7EED\u7684\u793E\u533A\u6210\u957F\uFF0C\u73B0\u5728\uFF0CFesod\\n\u9879\u76EE\u6B63\u5F0F\u5B98\u5BA3\u52A0\u5165 Apache \u5B75\u5316\u5668\uFF0C\u8FD9\u662F Fesod \u9879\u76EE\u7684\u65B0\u8D77\u70B9\uFF0C\u610F\u5473\u7740\u5F00\u6E90\u793E\u533A\u5316\u534F\u4F5C\u5C06\u4F1A\u53D8\u5F97\u66F4\u52A0\u89C4\u8303\u4EE5\u53CA\u56FD\u9645\u5316\uFF01\\n\\n![blog-20250917](/img/blog/20250917-01.png)\\n\\n## \u7B80\u4ECB\\n\\nApache Fesod (Incubating) \u662F\u4E00\u4E2A\u9AD8\u6027\u80FD\u3001\u5185\u5B58\u9AD8\u6548\u7684 Java \u5E93\uFF0C\u7528\u4E8E\u8BFB\u5199\u7535\u5B50\u8868\u683C\u6587\u4EF6\uFF0C\u65E8\u5728\u7B80\u5316\u5F00\u53D1\u5E76\u786E\u4FDD\u53EF\u9760\u6027\u3002\u540D\u79F0 fesod\uFF08\u53D1\u97F3\u4E3A\\n`/\u02C8f\u025Bs\u0252d/`\uFF09\uFF0C\u662F \\"fast easy spreadsheet and other documents\\"\uFF08\u5FEB\u901F\u7B80\u5355\u7684\u7535\u5B50\u8868\u683C\u548C\u5176\u4ED6\u6587\u6863\uFF09\u7684\u9996\u5B57\u6BCD\u7F29\u5199\uFF0C\u8868\u8FBE\u4E86\u9879\u76EE\u7684\u8D77\u6E90\u3001\u80CC\u666F\u548C\u613F\u666F\u3002\\n\\nApache Fesod (Incubating) \u53EF\u4EE5\u4E3A\u5F00\u53D1\u8005\u548C\u4F01\u4E1A\u63D0\u4F9B\u6781\u5927\u7684\u81EA\u7531\u5EA6\u548C\u7075\u6D3B\u6027\u3002\u6211\u4EEC\u8BA1\u5212\u5728\u672A\u6765\u5F15\u5165\u66F4\u591A\u65B0\u529F\u80FD\uFF0C\u4EE5\u6301\u7EED\u63D0\u5347\u7528\u6237\u4F53\u9A8C\u548C\u5DE5\u5177\u53EF\u7528\u6027\u3002Apache\\nFesod (Incubating) \u81F4\u529B\u4E8E\u6210\u4E3A\u60A8\u5904\u7406\u7535\u5B50\u8868\u683C\u6587\u4EF6\u7684\u6700\u4F73\u9009\u62E9\u3002\\n\\n## \u7279\u6027\\n\\n- **\u9AD8\u6027\u80FD\u8BFB\u5199**\uFF1A\u4E13\u6CE8\u4E8E\u6027\u80FD\u4F18\u5316\uFF0C\u80FD\u591F\u9AD8\u6548\u5904\u7406\u5927\u89C4\u6A21\u7535\u5B50\u8868\u683C\u6570\u636E\u3002\u4E0E\u4E00\u4E9B\u4F20\u7EDF\u7684\u7535\u5B50\u8868\u683C\u5904\u7406\u5E93\u76F8\u6BD4\uFF0C\u5B83\u53EF\u4EE5\u663E\u8457\u51CF\u5C11\u5185\u5B58\u6D88\u8017\u3002\\n- **\u7B80\u5355\u6613\u7528**\uFF1A\u8BE5\u5E93\u63D0\u4F9B\u4E86\u7B80\u5355\u76F4\u89C2\u7684 API\uFF0C\u4F7F\u5F00\u53D1\u8005\u80FD\u591F\u8F7B\u677E\u5C06\u5176\u96C6\u6210\u5230\u9879\u76EE\u4E2D\uFF0C\u65E0\u8BBA\u662F\u7B80\u5355\u7684\u7535\u5B50\u8868\u683C\u64CD\u4F5C\u8FD8\u662F\u590D\u6742\u7684\u6570\u636E\u5904\u7406\u3002\\n- **\u6D41\u5F0F\u64CD\u4F5C**\uFF1A\u652F\u6301\u6D41\u5F0F\u8BFB\u53D6\uFF0C\u6700\u5927\u7A0B\u5EA6\u5730\u51CF\u5C11\u4E00\u6B21\u6027\u52A0\u8F7D\u5927\u91CF\u6570\u636E\u7684\u95EE\u9898\u3002\u8FD9\u4E00\u8BBE\u8BA1\u5728\u5904\u7406\u6570\u5341\u4E07\u751A\u81F3\u6570\u767E\u4E07\u884C\u6570\u636E\u65F6\u5C24\u5176\u91CD\u8981\u3002\\n\\n## \u53D1\u5C55\u73B0\u72B6\\n\\n\u9879\u76EE\u7531\u539F\u6838\u5FC3\u7EF4\u62A4\u8005\u4E8E 2024 \u5E74\u53D1\u8D77\uFF0C\u65E8\u5728\u63D0\u4F9B\u66F4\u9AD8\u6548\u7684 Excel \u5904\u7406\u89E3\u51B3\u65B9\u6848\uFF0C\u5E76\u786E\u4FDD\u957F\u671F\u53EF\u6301\u7EED\u7684\u7EF4\u62A4\u3002\u5F00\u6E90\u4EE5\u6765\u5DF2\u521D\u6B65\u5EFA\u7ACB\u8D77\u4E86\u4E00\u4E2A\u5C0F\u578B\u793E\u533A\uFF0C\u4E3B\u4ED3\u5E93\u5728\\nGitHub \u7D2F\u8BA1\u6536\u83B7 **5.0K+** star, \u7D2F\u8BA1\u53D1\u5E03\u793E\u533A\u7248\u672C **5** \u6B21\uFF0C\u62E5\u6709 **20+** \u4F4D\u8D21\u732E\u8005\u3002\\n\\n\u6211\u4EEC\u9646\u7EED\u6536\u5230\u4E86\u6765\u81EA\u793E\u533A\u7684\u5E7F\u6CDB\u5173\u6CE8\u548C\u652F\u6301\uFF0C\u8FD9\u65E2\u662F\u5BF9\u6211\u4EEC\u8FC7\u53BB\u5DE5\u4F5C\u7684\u8BA4\u53EF\uFF0C\u4E5F\u662F\u5BF9\u6211\u4EEC\u672A\u6765\u53D1\u5C55\u7684\u671F\u671B\u3002\\n\\n![blog-20250917](/img/blog/20250917-02.png)\\n\\n## \u4E3A\u4F55\u52A0\u5165\u5B75\u5316\u5668\\n\\n\u52A0\u5165 Apache \u5B75\u5316\u5668\u4E3B\u8981\u662F\u57FA\u4E8E\u4EE5\u4E0B\u51E0\u4E2A\u539F\u56E0:\\n\\n- \u5728 Apache \u6210\u719F\u5F00\u6E90\u57FA\u91D1\u4F1A\u7684\u6307\u5BFC\u4E0B, \u8BA9\u5F00\u6E90\u9879\u76EE\u534F\u4F5C\u548C\u793E\u533A\u6CBB\u7406\u8FD0\u8425\u90FD\u66F4\u52A0\u89C4\u8303\u3002\\n- \u6784\u5EFA\u66F4\u52A0\u7E41\u8363\u548C\u591A\u6837\u5316\u7684\u5F00\u53D1\u8005\u793E\u533A, \u6211\u4EEC\u5E0C\u671B\u53EF\u4EE5\u5438\u5F15\u66F4\u591A\u4F18\u79C0\u7684\u6D77\u5185\u5916\u5F00\u53D1\u8005\u52A0\u5165, \u8BA9\u5F00\u53D1\u8005\u793E\u533A\u66F4\u52A0\u591A\u6837\u5316\u3002\\n- \u6269\u5927\u5E94\u7528\u8303\u56F4\uFF0C\u9F13\u52B1\u5C06\u5176\u96C6\u6210\u5230\u66F4\u591A\u5F00\u6E90\u548C\u5546\u4E1A\u9879\u76EE\u4E2D\uFF0C\u63A8\u52A8\u65B0\u7684\u7528\u4F8B\u548C\u529F\u80FD\u5F00\u53D1\u3002\\n\\n\u63A5\u4E0B\u6765\u793E\u533A\u4F1A\u5728 Apache \u5B75\u5316\u5668\u5BFC\u5E08\u7684\u5F15\u5BFC\u4E0B, \u9075\u4ECE \u201CCommunity over Code\u201D \u7684\u7406\u5FF5\u6765\u7BA1\u7406\u548C\u8FD0\u8425\u793E\u533A,\\n\u4E5F\u8BA9\u6BCF\u4E2A\u4F18\u79C0\u8D21\u732E\u8005\u90FD\u80FD\u591F\u88AB\u770B\u89C1\u3002\u5728\u5F00\u6E90\u4EA7\u54C1\u5C42\u9762\uFF0C\u503E\u542C\u7528\u6237\u58F0\u97F3\uFF0C\u63D0\u5347\u4F18\u5316\u4EA7\u54C1\u4F7F\u7528\u4F53\u9A8C\uFF0C\u6253\u9020\u5BF9\u63A5\u5F00\u6E90\u751F\u6001\u3002\\n\\n## \u5BFC\u5E08\u4ECB\u7ECD\\n\\n- tison(Champion)\\n- Dave Fisher\\n- PJ Fanning\\n- Huajie Wang\\n\\n\u611F\u8C22\u5404\u4F4D\u5BFC\u5E08\u65E0\u79C1\u7684\u5E2E\u52A9, \u5728\u5408\u89C4\u548C\u6D41\u7A0B\u63A8\u8FDB\u4E0A\u7684\u7ED9\u4E88\u4E86\u4E13\u4E1A\u6307\u5BFC\u3002\u7279\u522B\u611F\u8C22\u9879\u76EE\u7684 Champion\\n@tison\uFF0C\u5728\u9879\u76EE\u8FDB\u5165\u5B75\u5316\u5668\u7684\u8FC7\u7A0B\u4E2D\u4E3B\u5BFC\u4E86\u9879\u76EE\u4ECE\u8349\u6848\u8D77\u8349\u9636\u6BB5\u5230\u8BA8\u8BBA\u518D\u5230\u53D1\u8D77\u6295\u7968\u6574\u4E2A\u8FC7\u7A0B,\\n\u7ED9\u4E86\u5F88\u591A\u4E13\u4E1A\u7684\u5EFA\u8BAE\u548C\u6307\u5BFC\u3002\\n\\n\u76F8\u4FE1\u672A\u6765\u5728\u5404\u4F4D\u5BFC\u5E08\u7684\u6307\u5BFC\u4E0B\u793E\u533A\u4E00\u5B9A\u66F4\u52A0\u5065\u5EB7\u7684\u6210\u957F\u3002\\n\\n## \u52A0\u5165\u6211\u4EEC\\n\\n**\u9879\u76EE\u5730\u5740**\\n\\n- <https://github.com/apache/fesod>\\n\\n**\u5B98\u65B9\u7F51\u5740**\\n\\n- <https://fesod.apache.org/>\\n\\n**\u90AE\u4EF6\u5217\u8868**\\n\\n- <dev@fesod.apache.org>"}]}}')}}]);